SELECT id, user_id AS userId, api_key_name AS apiKeyName, api_key_hash AS apiKeyHash, hash_version AS hashVersion, masked_key AS maskedKey, status, expire_time AS expireTime, last_used_time AS lastUsedTime, last_used_ip AS lastUsedIp, remark, tenant_id AS tenantId, deleted, delete_op AS deleteOp, delete_time AS deleteTime, create_op AS createOp, create_time AS createTime, modify_op AS modifyOp, modify_time AS modifyTime FROM sys_api_key WHERE deleted = 0 AND user_id = #{userId}
AND api_key_name LIKE CONCAT('%', #{query.apiKeyName}, '%')
ORDER BY create_time DESC

